action.command:
cd /workspace && docker exec workspace-tika-1 sh -c 'printf "<html><body><h1>DOCX Validation</h1><p>Office document extraction test content for open_taki.</p></body></html>" > /tmp/d.html && pandoc /tmp/d.html -o /tmp/d.docx && echo created' && docker cp workspace-tika-1:/tmp/d.docx /tmp/d.docx && echo "=== DOCX extraction ===" && curl -sS -w '
HTTP:%{http_code}
' -X PUT -H 'Content-Type: application/vnd.openxmlformats-officedocument.wordprocessingml.document' --data-binary @/tmp/d.docx http://localhost:9998/rmeta/text 2>&1 | head -5 && echo "=== v2 protocol ===" && curl -sS -w '
HTTP:%{http_code}
' -X PUT -H 'Content-Type: text/plain' -H 'X-Taki-Protocol: v2' -H 'X-Taki-Features: meta,entities,summary' -H 'X-Taki-Source-Ref: space-1/doc.txt' --data-binary 'Contract between Max Mustermann and ACME GmbH.' http://localhost:9998/rmeta/text 2>&1 | head -5
